import { createHash } from 'node:crypto';
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { publicFiles } from './manage.mjs';
import { consoleFiles, validatePrebuilt } from './prebuilt.mjs';

// CI only: source comes from the exact Git commit, never the machine's private
// working files or the route tree regenerated by the console build.
export function stageRelease(root, destination) {
  if (existsSync(destination)) throw new Error('Release destination must not exist');
  const git = args => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', windowsHide: true }).trim();
  const commit = git(['rev-parse', 'HEAD']);
  if (!/^[a-f0-9]{40}$/.test(commit)) throw new Error('Invalid release commit');
  const generated = consoleFiles(root);
  const work = mkdtempSync(path.join(tmpdir(), 'kuku-release-'));
  try {
    const archive = path.join(work, 'source.tar'), source = path.join(work, 'source');
    mkdirSync(source);
    git(['archive', '--format=tar', '-o', archive, commit]);
    execFileSync('tar', ['-xf', archive, '-C', source], { windowsHide: true });
    mkdirSync(destination, { recursive: true });
    for (const name of publicFiles(source).keys()) {
      if (name === 'release.json') throw new Error('release.json must not be tracked in Git');
      const target = path.join(destination, name);
      mkdirSync(path.dirname(target), { recursive: true }); copyFileSync(path.join(source, name), target);
    }
    // Copy only outputs that were inspected and hashed above.
    for (const name of Object.keys(generated)) {
      const target = path.join(destination, name);
      mkdirSync(path.dirname(target), { recursive: true }); copyFileSync(path.join(root, name), target);
    }
    const manifest = { format: 1, commit, version: JSON.parse(readFileSync(path.join(destination, 'package.json'), 'utf8')).version, console: generated };
    writeFileSync(path.join(destination, 'release.json'), JSON.stringify(manifest, null, 2) + '\n');
    validatePrebuilt(destination);
    return manifest;
  } finally {
    if (path.dirname(work) !== tmpdir() || !path.basename(work).startsWith('kuku-release-')) throw new Error('Unsafe release cleanup path');
    rmSync(work, { recursive: true, force: true });
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
  const output = path.resolve(process.argv[2] || path.join(root, '.runtime/release'));
  const source = path.join(output, 'package');
  const manifest = stageRelease(root, source);
  const tar = path.join(output, 'kuku2api.tar.gz'), zip = path.join(output, 'kuku2api.zip');
  execFileSync('tar', ['-czf', tar, '-C', source, '.'], { windowsHide: true });
  execFileSync('zip', ['-qr', zip, '.'], { cwd: source, windowsHide: true });
  const checksum = file => createHash('sha256').update(readFileSync(file)).digest('hex');
  writeFileSync(path.join(output, 'SHA256SUMS'), `${checksum(tar)}  kuku2api.tar.gz\n${checksum(zip)}  kuku2api.zip\n`);
  console.log(`Prebuilt release packaged: ${manifest.commit}`);
}
